// #1057 · Public mini-puzzle page (mini/AAAA-MM-JJ.html, generated by
// scripts/mini-calendar.mjs). Static, no account, no Supabase, no write: only a
// local "solved" flag and anonymous hits on a static pixel (aggregated from the
// o2switch access log, see docs/marketing/ACQUISITION_ORGANIQUE.md).
import { isSolved, parisDay, placementConflicts } from './mini-puzzle.js';
import { miniLocale, miniTranslator } from './locales.js';
import { campaignUrl, discoveryUrlFor } from '../analytics/acquisition.js';

// Same territory palette as the game board (src/ui/game-screen.js).
export const TERRITORY_COLORS = ['#46c7e8', '#6d8fe8', '#8b70d7', '#49b49b', '#d38a54', '#b55f86', '#67a6bf', '#7e9c69', '#a8875b'];
const DONE_KEY = 'lumenMiniDoneV1';
const SOURCES = new Set(['facebook_daily', 'facebook', 'instagram', 'mini_share', 'mini_puzzle']);
const SITE = 'https://lumen.nopuna.fr';

function readDone(storage) {
  try {
    const value = JSON.parse(storage?.getItem(DONE_KEY) || '[]');
    return new Set(Array.isArray(value) ? value.filter((d) => typeof d === 'string').slice(-400) : []);
  } catch {
    return new Set();
  }
}
function writeDone(storage, done) {
  try {
    storage?.setItem(DONE_KEY, JSON.stringify([...done].sort().slice(-400)));
  } catch {}
}

// Anonymous, aggregated hit: event, day, language and a reviewed source code only.
export function hitUrl(event, { day, locale, search = '' }) {
  const raw = new URLSearchParams(search).get('utm_source');
  const source = SOURCES.has(raw) ? raw : 'direct';
  const url = new URL('/mini/t.gif', SITE);
  url.searchParams.set('e', event);
  url.searchParams.set('d', day);
  url.searchParams.set('l', locale);
  url.searchParams.set('s', source);
  return url.pathname + url.search;
}

export function ctaLinks(day, locale) {
  const campaign = 'mini_' + day;
  return {
    discover: campaignUrl(discoveryUrlFor(locale), 'mini_puzzle', { campaign }),
    install: campaignUrl(SITE + '/?install=1', 'mini_puzzle', { campaign, keep: ['install'] }),
    official: campaignUrl(SITE + '/?daily=1', 'mini_puzzle', { campaign, keep: ['daily'] }),
  };
}

function formatDay(day, locale) {
  const [y, m, d] = day.split('-').map(Number);
  return new Intl.DateTimeFormat(locale, { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' }).format(
    new Date(Date.UTC(y, m - 1, d)),
  );
}

export function figureSvg(figure, doc) {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = doc.createElementNS(ns, 'svg');
  if (!figure?.pts?.length) return svg;
  const xs = figure.pts.map((p) => p[0]),
    ys = figure.pts.map((p) => p[1]);
  const [x0, x1, y0, y1] = [Math.min(...xs), Math.max(...xs), Math.min(...ys), Math.max(...ys)];
  const W = 300,
    H = 160,
    s = Math.min(W / (x1 - x0 || 1), H / (y1 - y0 || 1));
  const P = ([x, y]) => [(x - x0) * s + 20, (y - y0) * s + 20];
  svg.setAttribute('viewBox', '0 0 ' + (W + 40) + ' ' + (H + 40));
  svg.setAttribute('class', 'mini-figure');
  svg.setAttribute('aria-hidden', 'true');
  for (const [a, b] of figure.edges) {
    const line = doc.createElementNS(ns, 'line');
    const [ax, ay] = P(figure.pts[a]),
      [bx, by] = P(figure.pts[b]);
    Object.entries({ x1: ax, y1: ay, x2: bx, y2: by }).forEach(([k, v]) => line.setAttribute(k, v.toFixed(1)));
    svg.append(line);
  }
  for (const pt of figure.pts) {
    const star = doc.createElementNS(ns, 'circle');
    const [x, y] = P(pt);
    star.setAttribute('cx', x.toFixed(1));
    star.setAttribute('cy', y.toFixed(1));
    star.setAttribute('r', '6');
    svg.append(star);
  }
  return svg;
}

export function mountMiniGame(root, { data, win = globalThis.window, now = () => new Date() } = {}) {
  const doc = root.ownerDocument;
  const storage = (() => {
    try {
      return win.localStorage;
    } catch {
      return null;
    }
  })();
  const locale = miniLocale({ storage, navigator: win.navigator, search: win.location?.search || '' });
  const t = miniTranslator(locale);
  // Owner acceptance before the Paris date: ?preview=1 opens the board and sends no hit.
  const preview = new URLSearchParams(win.location?.search || '').get('preview') === '1';
  const today = preview ? data.day : parisDay(now());
  doc.documentElement.lang = locale;
  const hit = (event) => {
    if (preview) return;
    try {
      const img = new win.Image();
      img.src = hitUrl(event, { day: data.day, locale, search: win.location?.search || '' });
    } catch {}
  };
  const $ = (id) => doc.getElementById(id);
  const text = (id, value) => {
    const node = $(id);
    if (node) node.textContent = value;
  };
  text('mini-kicker', data.door ? t('mini.advent', { door: data.door }) : t('mini.kicker'));
  text('mini-date', formatDay(data.day, locale) + ' · ' + t('mini.timeZone'));
  text('mini-title', t('mini.titleMany', { count: data.missing }));
  text('mini-rules', t('mini.rules'));
  text('mini-how', t('mini.howTo'));
  text('mini-note', t('mini.noAccount'));
  text('mini-archive-link', t('mini.archive'));
  const board = $('mini-board'),
    status = $('mini-status'),
    winPanel = $('mini-win');

  if (!data.enabled) {
    root.dataset.state = 'paused';
    status.textContent = t('mini.paused');
    return { state: 'paused', locale };
  }
  if (data.day > today) {
    root.dataset.state = 'locked';
    status.textContent = t('mini.locked', { date: formatDay(data.day, locale) });
    return { state: 'locked', locale };
  }

  const n = data.size,
    reg = data.reg;
  const given = new Set(data.given.map(([r, c]) => r + ',' + c));
  const state = Array.from({ length: n }, () => Array(n).fill(0));
  for (const [r, c] of data.given) state[r][c] = 2;
  const done = readDone(storage);
  const cells = [];
  board.style.setProperty('--n', n);
  board.setAttribute('role', 'grid');
  for (let r = 0; r < n; r++) {
    const row = doc.createElement('div');
    row.setAttribute('role', 'row');
    row.className = 'mini-row';
    for (let c = 0; c < n; c++) {
      const cell = doc.createElement('button');
      cell.type = 'button';
      cell.className = 'mini-cell';
      cell.setAttribute('role', 'gridcell');
      cell.style.setProperty('--territory', TERRITORY_COLORS[reg[r][c] % TERRITORY_COLORS.length]);
      // Territory borders: a thicker line where the neighbour belongs to another territory.
      if (r > 0 && reg[r - 1][c] !== reg[r][c]) cell.classList.add('edge-top');
      if (c > 0 && reg[r][c - 1] !== reg[r][c]) cell.classList.add('edge-left');
      if (given.has(r + ',' + c)) cell.classList.add('given');
      cell.addEventListener('click', () => tap(r, c));
      cells.push({ r, c, node: cell });
      row.append(cell);
    }
    board.append(row);
  }
  const guardians = () => {
    const out = [];
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (state[r][c] === 2) out.push([r, c]);
    return out;
  };
  let won = false;
  function render() {
    const list = guardians();
    const bad = placementConflicts(reg, list);
    for (const { r, c, node } of cells) {
      const value = state[r][c],
        key = r + ',' + c;
      node.dataset.value = String(value);
      node.textContent = value === 2 ? '✦' : value === 1 ? '×' : '';
      node.classList.toggle('conflict', bad.has(key));
      node.disabled = given.has(key) || won;
      const label = given.has(key)
        ? 'mini.cellGiven'
        : value === 2
          ? 'mini.cellGuardian'
          : value === 1
            ? 'mini.cellCross'
            : 'mini.cell';
      node.setAttribute('aria-label', t(label, { row: r + 1, col: c + 1 }));
    }
    const remaining = Math.max(0, n - list.length);
    status.textContent = bad.size ? t('mini.conflict') : won ? t('mini.winTitle') : t('mini.remaining', { count: remaining });
    status.dataset.kind = bad.size ? 'conflict' : won ? 'won' : 'info';
  }
  function tap(r, c) {
    if (won || given.has(r + ',' + c)) return;
    state[r][c] = (state[r][c] + 1) % 3;
    render();
    if (isSolved(reg, guardians())) showWin(true);
  }
  function showWin(fresh) {
    won = true;
    root.dataset.state = 'won';
    render();
    if (fresh && !done.has(data.day)) {
      done.add(data.day);
      writeDone(storage, done);
      hit('win');
    }
    const name = data.constellation?.names?.[locale] || data.constellation?.names?.fr || '';
    text('mini-win-title', t('mini.winTitle'));
    text('mini-win-text', name ? t('mini.winText', { constellation: name }) : t('mini.winGeneric'));
    const figure = $('mini-win-figure');
    if (figure && !figure.firstChild) figure.append(figureSvg(data.constellation?.figure, doc));
    const links = ctaLinks(data.day, locale);
    for (const [id, key, href, event] of [
      ['mini-cta-discover', 'mini.ctaDiscover', links.discover, 'cta_discover'],
      ['mini-cta-install', 'mini.ctaInstall', links.install, 'cta_install'],
      ['mini-cta-official', 'mini.ctaOfficial', links.official, 'cta_official'],
    ]) {
      const a = $(id);
      if (!a) continue;
      a.textContent = t(key);
      a.href = href;
      a.onclick = () => hit(event);
    }
    text('mini-cta-note', t('mini.ctaDiscoverNote'));
    winPanel.hidden = false;
    // On a phone the calls to action sit below the board: bring them into view.
    if (fresh && typeof winPanel.scrollIntoView === 'function') {
      const reduced = win.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
      winPanel.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
    }
  }
  const reset = $('mini-reset');
  reset.textContent = t('mini.reset');
  reset.onclick = () => {
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) if (!given.has(r + ',' + c)) state[r][c] = 0;
    won = false;
    root.dataset.state = 'playing';
    winPanel.hidden = true;
    render();
  };
  const share = $('mini-share');
  if (share) {
    share.textContent = t('mini.share');
    share.onclick = async () => {
      const url = SITE + '/mini/' + data.day + '.html?utm_source=mini_share&utm_medium=referral';
      const textValue = t('mini.shareText', { date: formatDay(data.day, locale) });
      hit('share');
      try {
        if (win.navigator.share) return await win.navigator.share({ title: 'LUMEN', text: textValue, url });
        await win.navigator.clipboard.writeText(textValue + ' ' + url);
        share.textContent = t('mini.copied');
      } catch {}
    };
  }
  root.dataset.state = 'playing';
  render();
  hit('view');
  if (done.has(data.day)) text('mini-done', t('mini.done'));
  return { state: 'playing', locale, tap, guardians };
}

if (globalThis.document?.getElementById('mini-data') && !globalThis.__LUMEN_MINI_TEST__) {
  const data = JSON.parse(document.getElementById('mini-data').textContent);
  mountMiniGame(document.getElementById('mini'), { data });
}
